// @name Connect four
// @background #f4efe6
// @refresh 3600
// Connect four for a touch screen: tap anywhere in a column to drop a disc
// there. Play the computer (four levels) or a friend on the same frame. The
// game in progress and the score are kept on the frame.
import { COLS, ROWS, replay, bestMove } from './logic'
import { highContrast, canvasOf, Button, OptionsPage, Title, titleSize, textH, fitText, fitWidth, withText, roundRoom, RimButton, SlidersGlyph } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f4efe6] text-[#1f2a37]',
    muted: 'text-[#5b6472]',
    button: 'bg-[#e4dccd] text-[#1f2a37] active:bg-[#d6ccb8]',
    primary: 'bg-[#1f3a5f] text-white active:bg-[#2b4c78]',
    on: 'bg-[#1f3a5f] text-white',
    off: 'bg-[#e4dccd] text-[#1f2a37]',
    banner: 'bg-[#1f3a5f] text-white',
    board: '#1f3a5f',
    boardEdge: '#162c49',
    hole: '#f4efe6',
    holeEdge: '#162c49',
    discs: ['', '#c8553d', '#e8b33a'],
    discEdge: ['', '#9c3f2c', '#b98a22'],
    mark: ['', '#f4efe6', '#1f3a5f'],
    names: ['', 'Red', 'Gold'],
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    banner: 'bg-black text-white',
    board: '#ffffff',
    boardEdge: '#000000',
    hole: '#ffffff',
    holeEdge: '#000000',
    discs: ['', '#000000', '#ffffff'],
    discEdge: ['', '#000000', '#000000'],
    mark: ['', '#ffffff', '#000000'],
    names: ['', 'Black', 'White'],
  },
}

const OPTIONS = [
  { field: 'opponent', label: 'Opponent', options: [['computer', 'Computer'], ['human', 'Two players']] },
  { field: 'level', label: 'Computer level', options: [['easy', 'Easy'], ['medium', 'Medium'], ['hard', 'Hard'], ['expert', 'Expert']] },
  { field: 'starts', label: 'Who starts', options: [['you', 'You'], ['computer', 'Computer'], ['alternate', 'Take turns']] },
]

// The game in progress, kept in the scene's private `game` field so it
// outlasts a restart: the columns played and who went first.
type Game = { moves: number[]; first: number; counted?: boolean }
type Score = { p1: number; p2: number; draws: number }

const settingsOf = (app) => ({
  vsComputer: (app.state.opponent || 'computer') !== 'human',
  level: app.state.level || 'medium',
  starts: app.state.starts || 'you',
})

const loadGame = (app): Game => {
  const g = app.state.game
  if (g && Array.isArray(g.moves) && (g.first === 1 || g.first === 2)) return g
  return newGame(app, null)
}
const loadScore = (app): Score => {
  const s = app.state.score
  return s && typeof s === 'object' ? { p1: s.p1 || 0, p2: s.p2 || 0, draws: s.draws || 0 } : { p1: 0, p2: 0, draws: 0 }
}

// Player 1 is you against the computer. "Take turns" swaps who opens.
const newGame = (app, previous: Game | null): Game => {
  const { starts } = settingsOf(app)
  const first = starts === 'computer' ? 2 : starts === 'alternate' && previous ? 3 - previous.first : 1
  return { moves: [], first }
}

const save = (game: Game) => frameos.setState('game', game)

// Adds (or with -1 takes back) a finished game to the tally.
const count = (app, winner: number, by: number) => {
  const score = loadScore(app)
  if (winner === 1) score.p1 += by
  else if (winner === 2) score.p2 += by
  else if (winner === 3) score.draws += by
  frameos.setState('score', score)
}

// A disc into a column, if the game is on and the column has room. Against
// the computer only your discs come from here.
const drop = (app, col: number) => {
  const game = loadGame(app)
  const state = replay(game.moves, game.first)
  if (state.winner || col < 0 || col >= COLS || state.pos.heights[col] >= ROWS) return
  if (settingsOf(app).vsComputer && state.toMove !== 1) return
  game.moves = [...game.moves, col]
  save(settle(app, game))
}

// The computer's moves while it is its turn, and the score once a game ends.
const settle = (app, game: Game): Game => {
  const { vsComputer, level } = settingsOf(app)
  let state = replay(game.moves, game.first)
  if (vsComputer && !state.winner && state.toMove === 2) {
    const col = bestMove(state.pos, 2, level, Math.random)
    if (col >= 0) {
      game = { ...game, moves: [...game.moves, col] }
      state = replay(game.moves, game.first)
    }
  }
  if (state.winner && !game.counted) {
    count(app, state.winner, 1)
    game = { ...game, counted: true }
  }
  return game
}

// Back to your last turn against the computer, one disc with two players.
const undo = (app) => {
  const game = loadGame(app)
  if (!game.moves.length) return
  const { vsComputer } = settingsOf(app)
  const mover = (i: number) => (i % 2 === 0 ? game.first : 3 - game.first)
  const moves = game.moves.slice()
  if (game.counted) count(app, replay(moves, game.first).winner, -1)
  if (vsComputer) {
    while (moves.length && mover(moves.length - 1) === 2) moves.pop()
    if (moves.length) moves.pop()
  } else {
    moves.pop()
  }
  save({ moves, first: game.first })
}

const restart = (app) => {
  save(settle(app, newGame(app, loadGame(app))))
  frameos.remember('page', null)
}

// What each slot of the board shows, one signal a slot, and the lines beside
// it: a tap runs only the slots and lines that read what it changed, not
// get(). The game itself stays in the scene's `game` field.
const slots = Array.from({ length: COLS * ROWS }, () => signal(''))
const status = signal('')
const statusWho = signal(0)
const scoreText = signal('')
const over = signal(false)

// Every signal from the game and the score. A slot's look: "" a hole, "1" or
// "2" a disc, with "r" when it is in the winning four, "d" when it is the
// last disc played.
const show = (app, game: Game) => {
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const { vsComputer } = settingsOf(app)
  const state = replay(game.moves, game.first)
  for (let cell = 0; cell < COLS * ROWS; cell++) {
    const who = state.pos.cells[cell]
    slots[cell].value = !who ? '' : state.four.includes(cell) ? `${who}r` : cell === state.lastCell && !state.winner ? `${who}d` : `${who}`
  }
  const score = loadScore(app)
  const name = (who: number) => (vsComputer ? (who === 1 ? 'You' : 'Computer') : t.names[who])
  status.value =
    state.winner === 3 ? 'A draw'
    : state.winner ? (vsComputer ? (state.winner === 1 ? 'You win!' : 'The computer wins') : `${t.names[state.winner]} wins!`)
    : vsComputer ? 'Your turn' : `${t.names[state.toMove]} to play`
  statusWho.value = state.winner === 3 ? 0 : state.winner || state.toMove
  scoreText.value = `${name(1)} ${score.p1} · ${name(2)} ${score.p2}${score.draws ? ` · Draws ${score.draws}` : ''}`
  over.value = !!state.winner
}

// After a handler: what get() does first (the computer's move when it is its
// turn), then every signal, so the picture is the one a whole get() draws.
const refresh = (app) => {
  let game = loadGame(app)
  const settled = settle(app, game)
  if (settled !== game) {
    game = settled
    save(game)
  }
  show(app, game)
}

// Buttons and keys on frames without a touch screen: back is undo, forward a
// new game once this one is over; on a keyboard 1-7 drop a disc.
export function onEvent(app, context) {
  const event = context.event
  if (event === 'back') undo(app)
  else if (event === 'forward') {
    const game = loadGame(app)
    if (!replay(game.moves, game.first).winner) return false
    restart(app)
  } else if (event === 'keyDown') {
    const p = context.payload || {}
    if (p.ctrl || p.alt || p.meta) return false
    const key = String(p.key || '').toLowerCase()
    if (key >= '1' && key <= '7') drop(app, Number(key) - 1)
    else if (key === 'backspace' || key === 'u') undo(app)
    else if (key === 'n') restart(app)
    else return false
  } else return false
  return true
}

// One slot of the board, drawn from its look: a ring on the winning four, a
// dot on the last disc.
const Slot = memo(({ cell, t }) => {
  const look = slots[cell].value
  const cx = Math.floor(cell / ROWS) * 100 + 50
  const cy = (ROWS - 1 - (cell % ROWS)) * 100 + 50
  if (!look) return <g><circle cx={cx} cy={cy} r={38} fill={t.hole} stroke={t.holeEdge} strokeWidth={4} /></g>
  const who = Number(look[0])
  return (
    <g>
      <circle cx={cx} cy={cy} r={38} fill={t.discs[who]} stroke={t.discEdge[who]} strokeWidth={5} />
      {look[1] === 'r' ? <circle cx={cx} cy={cy} r={17} fill="none" stroke={t.mark[who]} strokeWidth={9} /> : null}
      {look[1] === 'd' ? <circle cx={cx} cy={cy} r={9} fill={t.mark[who]} /> : null}
    </g>
  )
})

// The board as one drawing, 100 units a cell.
const Board = ({ t, width, height }) => {
  const discs = []
  for (let cell = 0; cell < COLS * ROWS; cell++) discs.push(<Slot cell={cell} t={t} />)
  return (
    <svg viewBox={`-8 -8 ${COLS * 100 + 16} ${ROWS * 100 + 16}`} width={width} height={height}>
      <rect x={-6} y={-6} width={COLS * 100 + 12} height={ROWS * 100 + 12} rx={22} fill={t.board} stroke={t.boardEdge} strokeWidth={4} />
      {discs}
    </svg>
  )
}

const Swatch = ({ t, who, size }) => (
  <svg viewBox="0 0 40 40" className={`w-[${size}px] h-[${size}px]`}>
    <circle cx={20} cy={20} r={16} fill={t.discs[who]} stroke={t.discEdge[who] === t.discs[who] ? t.holeEdge : t.discEdge[who]} strokeWidth={3} />
  </svg>
)

// The lines and the button a move changes, each reading its signals.
const StatusLine = memo(({ ui, t }) => (
  <div className={`flex items-center gap-[${ui.gap}px]`}>
    {statusWho.value ? <Swatch t={t} who={statusWho.value} size={Math.round(ui.big * 1.2)} /> : null}
    <span className={`text-[${ui.big}px] font-bold leading-tight`}>{status.value}</span>
  </div>
))
const ScoreLine = memo(({ ui, t }) => <span className={`text-[${ui.small}px] ${t.muted}`}>{scoreText.value}</span>)
const NewButton = memo(({ ui, t, app, grow }) => (
  <Button ui={ui} grow={grow} className={over.value ? t.primary : t.button} onClick={() => { restart(app); refresh(app) }}>New game</Button>
))

// On a round panel: whose turn it is over the score, centred in the arc above the board.
const RoundStatus = memo(({ size, small, t }) => (
  <div className="flex flex-col items-center gap-1">
    <div className="flex items-center gap-2">
      {statusWho.value ? <Swatch t={t} who={statusWho.value} size={Math.round(size * 1.2)} /> : null}
      <span className={`text-[${size}px] font-bold leading-tight`}>{status.value}</span>
    </div>
    <span className={`text-[${small}px] ${t.muted}`}>{scoreText.value}</span>
  </div>
))
const RoundNew = memo(({ w, h, size, t, app }) => (
  <div className={`w-[${w}px] h-[${h}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${size}px] font-semibold ${over.value ? t.primary : t.button}`}
    onClick={() => { restart(app); refresh(app) }}>
    New game
  </div>
))
const UNDO = 'M12.5 8c-2.65 0-5.05.99-6.9 2.6L2 7v9h9l-3.62-3.62c1.39-1.16 3.16-1.88 5.12-1.88 3.54 0 6.55 2.31 7.6 5.5l2.37-.78C21.08 11.03 17.15 8 12.5 8z'

// The sizes only change with the canvas: the same object while it does not,
// so the memo()'d parts are not run again for a new one.
let lastUi = null
const stableUi = (ui) => (lastUi && lastUi.W === ui.W && lastUi.H === ui.H ? lastUi : (lastUi = ui))

export function get(app, context) {
  const ui = stableUi(canvasOf(app, context))
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const { vsComputer } = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows = OPTIONS.filter((row) => vsComputer || row.field !== 'level').map((row) => ({
      ...row,
      value: app.state[row.field] || row.options[0][0],
      options: row.field === 'starts' && !vsComputer ? [['you', t.names[1]], ['computer', t.names[2]], ['alternate', 'Take turns']] : row.options,
    }))
    return (
      <OptionsPage ui={ui} t={t} title="Connect four" rows={rows}
        onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
    )
  }

  // The computer moves first when it opens, or after the settings changed.
  let game = loadGame(app)
  const settled = settle(app, game)
  if (settled !== game) {
    game = settled
    save(game)
  }
  show(app, game)

  // Round: the board in the square inside the circle, the status in the arc
  // above it, New game in the arc below between Undo and the options on the rim.
  if (ui.round) {
    const { side, chord, rimSpot } = roundRoom(ui.W, ui.H)
    const cell = Math.floor(side / (COLS + 0.16))
    const boardW = Math.round(cell * (COLS + 0.16))
    const boardH = Math.round(cell * (ROWS + 0.16))
    const top = (ui.H - boardH) >> 1
    const size = Math.max(16, Math.min(ui.big, Math.round(top * 0.24)))
    const d = Math.max(40, Math.round(ui.button * 0.86))
    const [ux, uy] = rimSpot(d, boardH, true)
    const [ox, oy] = rimSpot(d, boardH, false)
    const bTop = top + boardH + 8
    const bh = Math.max(40, Math.min(ui.button, uy + d - bTop))
    const newW = Math.min(ox - ux - d - 16, chord(bTop + bh - ui.H / 2))
    return (
      <div className={`relative w-[${ui.W}px] h-[${ui.H}px] ${t.page}`}>
        <div className={`absolute left-0 top-0 w-[${ui.W}px] h-[${top - 6}px] flex items-end justify-center`}>
          <RoundStatus size={size} small={Math.max(14, Math.min(ui.small, size - 4))} t={t} />
        </div>
        <div className={`absolute left-[${(ui.W - boardW) >> 1}px] top-[${top}px] w-[${boardW}px] h-[${boardH}px]`}
          onClick={(e) => { drop(app, Math.floor((e.localX / e.width) * COLS)); refresh(app) }}>
          <Board t={t} width={boardW} height={boardH} />
        </div>
        <div className={`absolute left-[${(ui.W - newW) >> 1}px] top-[${bTop}px]`}>
          <RoundNew w={newW} h={bh} size={Math.min(ui.text, Math.round(bh * 0.4))} t={t} app={app} />
        </div>
        <RimButton x={ux} y={uy} d={d} className={t.button} onClick={() => { undo(app); refresh(app) }}>
          <svg viewBox="0 0 24 24" className={`w-[${Math.round(d * 0.5)}px] h-[${Math.round(d * 0.5)}px]`}><path d={UNDO} fill="currentColor" /></svg>
        </RimButton>
        <RimButton x={ox} y={oy} d={d} className={t.button} onClick={() => frameos.remember('page', 'options')}>
          <SlidersGlyph px={Math.round(d * 0.5)} />
        </RimButton>
      </div>
    )
  }

  // Side by side or stacked, whichever gives the bigger board.
  const sideW = Math.round(Math.max(ui.W * 0.28, ui.text * 9))
  const sideCell = Math.min((ui.W - sideW - ui.pad * 3) / COLS, (ui.H - ui.pad * 2) / ROWS)
  const barH = ui.button
  const stackCell = Math.min((ui.W - ui.pad * 2) / COLS, (ui.H - ui.pad * 2 - ui.gap * 2 - barH * 2) / ROWS)
  const side = sideCell >= stackCell
  const cell = Math.floor((side ? sideCell : stackCell) * 0.995)
  const boardW = Math.round(cell * (COLS + 0.16))
  const boardH = Math.round(cell * (ROWS + 0.16))

  const board = (
    <div className={`w-[${boardW}px] h-[${boardH}px] shrink-0`}
      onClick={(e) => { drop(app, Math.floor((e.localX / e.width) * COLS)); refresh(app) }}>
      <Board t={t} width={boardW} height={boardH} />
    </div>
  )
  const statusLine = <StatusLine ui={ui} t={t} />
  const scoreLine = <ScoreLine ui={ui} t={t} />
  // A drop, undo or new game here sets signals; the options page's New game
  // (restart without show) leaves the page, so it is a whole get().
  const undoAction = () => { undo(app); refresh(app) }
  const optionsAction = () => frameos.remember('page', 'options')
  const buttons = [
    <Button ui={ui} grow={!side} className={t.button} onClick={undoAction}>Undo</Button>,
    <NewButton ui={ui} t={t} app={app} grow={!side} />,
    <Button ui={ui} grow={!side} className={t.button} onClick={optionsAction}>Options</Button>,
  ]
  // A key with a glyph in place of a word, where the words would not fit.
  const key = (glyph, onClick) => (
    <div className={`w-[${ui.button}px] h-[${ui.button}px] shrink-0 rounded-xl flex items-center justify-center ${t.button}`} onClick={onClick}>{glyph}</div>
  )
  const glyph = Math.round(ui.button * 0.5)
  const undoGlyph = <svg viewBox="0 0 24 24" className={`w-[${glyph}px] h-[${glyph}px]`}><path d={UNDO} fill="currentColor" /></svg>

  if (side) {
    // The column beside the board. Where it is short (a 320x240 panel), the
    // name on one line and New game over Undo and Options side by side.
    const colW = ui.W - ui.pad * 3 - boardW
    const named = titleSize(ui, colW, 'Connect four')
    const full = textH('Connect four', `text-[${named}px] font-bold leading-tight`, named, colW) + ui.small * 1.5 + ui.big * 1.25 + ui.button * 3 + ui.gap * 7
    const tight = full > ui.H - ui.pad * 2
    const halfW = Math.floor((colW - ui.gap) / 2)
    const halfText = fitText('Options', halfW, ui.text)
    const half = withText(ui, halfText)
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        {board}
        <div className={`flex-1 h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={colW} line={tight}>Connect four</Title>
          {scoreLine}
          <div className="flex-1" />
          {statusLine}
          <div className="flex-1" />
          {tight ? (
            <div className={`space-y-[${ui.gap}px]`}>
              <NewButton ui={ui} t={t} app={app} grow={false} />
              {halfText >= 13 ? (
                <div className={`flex gap-[${ui.gap}px]`}>
                  <Button ui={half} grow className={t.button} onClick={undoAction}>Undo</Button>
                  <Button ui={half} grow className={t.button} onClick={optionsAction}>Options</Button>
                </div>
              ) : (
                <div className={`flex justify-between`}>
                  {key(undoGlyph, undoAction)}
                  {key(<SlidersGlyph px={glyph} />, optionsAction)}
                </div>
              )}
            </div>
          ) : (
            <div className={`space-y-[${ui.gap}px]`}>{buttons}</div>
          )}
        </div>
      </div>
    )
  }
  // The row under the board: the three words where each fits a third of it,
  // else (a watch) Undo and Options as keys with their glyphs beside New game.
  const keys = (ui.W - ui.pad * 2 - ui.gap * 2) / 3 < fitWidth('New game', ui.text)
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] items-center ${t.page}`}>
      {ui.H > ui.W * 1.25 ? <span className={`w-full text-[${ui.title}px] font-bold leading-tight`}>Connect four</span> : null}
      <div className={`flex items-center justify-between w-full h-[${barH}px]`}>
        {statusLine}
        {scoreLine}
      </div>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      {keys ? (
        <div className={`flex w-full gap-[${ui.gap}px]`}>
          {key(undoGlyph, undoAction)}
          <NewButton ui={ui} t={t} app={app} grow={true} />
          {key(<SlidersGlyph px={glyph} />, optionsAction)}
        </div>
      ) : (
        <div className={`flex w-full gap-[${ui.gap}px]`}>{buttons}</div>
      )}
    </div>
  )
}

sources.logic.ts:
// Connect four's rules and the computer player. Pure: no frameos calls, so it
// can be checked with plain node.
//
// The board is 7 columns of 6, cell = col * 6 + row, row 0 at the bottom.
// Players are 1 and 2. A game is the list of columns played, so undo is
// dropping the last one and the board is always rebuilt from the list.

export const COLS = 7
export const ROWS = 6
const CELLS = COLS * ROWS

// Every line of four on the board (69 of them), as cell numbers, and for
// each cell the lines through it. Built once when the module loads: small
// typed arrays, no objects.
const LINES = new Int8Array(69 * 4)
const CELL_LINES = new Int8Array(CELLS * 16).fill(-1)
const cellLineCount = new Int8Array(CELLS)
let lineCount = 0
for (const [dc, dr] of [[1, 0], [0, 1], [1, 1], [1, -1]]) {
  for (let c = 0; c < COLS; c++) {
    for (let r = 0; r < ROWS; r++) {
      const ec = c + dc * 3
      const er = r + dr * 3
      if (ec < 0 || ec >= COLS || er < 0 || er >= ROWS) continue
      for (let k = 0; k < 4; k++) {
        const cell = (c + dc * k) * ROWS + (r + dr * k)
        LINES[lineCount * 4 + k] = cell
        CELL_LINES[cell * 16 + cellLineCount[cell]] = lineCount
        cellLineCount[cell]++
      }
      lineCount++
    }
  }
}

// What a line is worth to its owner by how many of its four they hold (and
// none of the other player's): open threes matter, twos a little.
const LINE_VALUE = [0, 1, 6, 40, 0]
const CENTER_ORDER = [3, 2, 4, 1, 5, 0, 6]
export const WIN = 1000000

// A position the search plays moves into and takes them back from. It keeps
// per line how many discs each player has there, and the score from player
// 1's side, so a move updates only the lines through its cell (at most 13)
// and the evaluation is a lookup.
export class Position {
  cells = new Int8Array(CELLS)
  heights = new Int8Array(COLS)
  count1 = new Int8Array(69)
  count2 = new Int8Array(69)
  score = 0
  moves = 0

  lineValue(line: number) {
    const a = this.count1[line]
    const b = this.count2[line]
    if (a && b) return 0
    return a ? LINE_VALUE[a] : -LINE_VALUE[b]
  }

  // Plays `player` into column `col`; answers true when that move wins.
  play(col: number, player: number) {
    const cell = col * ROWS + this.heights[col]
    this.heights[col]++
    this.cells[cell] = player
    this.moves++
    let won = false
    const counts = player === 1 ? this.count1 : this.count2
    for (let i = 0; i < 16; i++) {
      const line = CELL_LINES[cell * 16 + i]
      if (line < 0) break
      this.score -= this.lineValue(line)
      counts[line]++
      if (counts[line] === 4) won = true
      this.score += this.lineValue(line)
    }
    return won
  }

  undo(col: number, player: number) {
    this.heights[col]--
    const cell = col * ROWS + this.heights[col]
    this.cells[cell] = 0
    this.moves--
    const counts = player === 1 ? this.count1 : this.count2
    for (let i = 0; i < 16; i++) {
      const line = CELL_LINES[cell * 16 + i]
      if (line < 0) break
      this.score -= this.lineValue(line)
      counts[line]--
      this.score += this.lineValue(line)
    }
  }
}

// The state of a game from its moves: the board, who is to move, the winner
// (0 none, 1, 2, or 3 for a full board) and the four that won.
export function replay(moves: number[], first: number) {
  const pos = new Position()
  let player = first
  let winner = 0
  let lastCell = -1
  for (const col of moves) {
    if (winner || pos.heights[col] >= ROWS) break
    lastCell = col * ROWS + pos.heights[col]
    if (pos.play(col, player)) winner = player
    player = 3 - player
  }
  if (!winner && pos.moves === CELLS) winner = 3
  return { pos, toMove: player, winner, lastCell, four: winner === 1 || winner === 2 ? winningCells(pos, winner) : [] }
}

export function winningCells(pos: Position, player: number) {
  const counts = player === 1 ? pos.count1 : pos.count2
  const cells: number[] = []
  for (let line = 0; line < lineCount; line++) {
    if (counts[line] === 4) for (let k = 0; k < 4; k++) cells.push(LINES[line * 4 + k])
  }
  return cells
}

// How hard the computer plays: how deep it looks and how many positions it
// may visit (an ESP32's QuickJS does a few thousand a second at most).
export const LEVELS = {
  easy: { depth: 2, nodes: 2000, noise: 60 },
  medium: { depth: 4, nodes: 4000, noise: 8 },
  hard: { depth: 6, nodes: 9000, noise: 0 },
  expert: { depth: 10, nodes: 20000, noise: 0 },
}

// The computer's move for `player` (alpha-beta search, centre columns
// first, deepening one ply at a time until the depth or the node budget).
// `random` is a function giving 0..1, for the easier levels' mistakes.
export function bestMove(pos: Position, player: number, level: string, random: () => number) {
  const cfg = LEVELS[level] || LEVELS.medium
  let nodes = 0
  let aborted = false

  const search = (depth: number, alpha: number, beta: number, who: number, ply: number): number => {
    nodes++
    if (nodes > cfg.nodes) {
      aborted = true
      return 0
    }
    if (pos.moves === CELLS) return 0
    if (depth === 0) return who === 1 ? pos.score : -pos.score
    let best = -WIN * 2
    for (let i = 0; i < 7; i++) {
      const col = CENTER_ORDER[i]
      if (pos.heights[col] >= ROWS) continue
      let value
      if (pos.play(col, who)) value = WIN - ply
      else value = -search(depth - 1, -beta, -alpha, 3 - who, ply + 1)
      pos.undo(col, who)
      if (aborted) return 0
      if (value > best) best = value
      if (value > alpha) alpha = value
      if (alpha >= beta) break
    }
    return best
  }

  // The root keeps every column's value, so the easy levels can pick among
  // the near-best and the order improves with each deeper pass.
  let order = CENTER_ORDER.filter((col) => pos.heights[col] < ROWS)
  if (!order.length) return -1
  let values: Record<number, number> = {}
  for (let depth = 1; depth <= cfg.depth; depth++) {
    const found: Record<number, number> = {}
    let alpha = -WIN * 2
    for (const col of order) {
      let value
      if (pos.play(col, player)) value = WIN
      // The easier levels need every column's real value; the others only
      // the best one, so they search a narrower window.
      else value = -search(depth - 1, -WIN * 2, cfg.noise ? WIN * 2 : -alpha, 3 - player, 1)
      pos.undo(col, player)
      if (aborted) break
      found[col] = value
      if (value > alpha) alpha = value
    }
    if (aborted) break
    values = found
    order = order.slice().sort((a, b) => values[b] - values[a])
    // A forced win or loss found: deeper looks change nothing.
    if (Math.abs(values[order[0]]) > WIN / 2) break
  }
  // Pick: the best, or for the easier levels any move within `noise` of it
  // (never one that throws a game away when a safe one exists).
  const best = values[order[0]]
  if (cfg.noise && best < WIN / 2) {
    const near = order.filter((col) => values[col] > -WIN / 2 && values[col] >= best - cfg.noise)
    if (near.length) return near[Math.floor(random() * near.length)]
  }
  return order[0]
}

